  Question(theme: "energy", text: "Après perte d’un groupe moteur, comment le SIE compense-t-il la perte de puissance ?", options: ["Il utilise les moteurs restants à 100 %", "Il coupe tous les moteurs", "Il passe automatiquement à 60 %", "Il recharge les batteries"], correct: {0}, explanation: "Le SIE utilise les moteurs restants à 100 % pour réduire la perte de puissance.", source: "p. 36", multi: false),
  Question(theme: "pneumatic", text: "Combien de compresseurs principaux produisent l’air comprimé ?", options: ["1", "2", "3", "4"], correct: {1}, explanation: "Le livret indique deux compresseurs principaux.", source: "p. 39", multi: false),
  Question(theme: "pneumatic", text: "Quels éléments composent chaque unité de production d’air ?", options: ["Groupe moto-compresseur", "Sécheur et filtres", "Manostat de régulation", "Manostat de secours"], correct: {0,1,2,3}, explanation: "Ces quatre éléments sont cités dans la composition de chaque unité.", source: "p. 39", multi: true),
  Question(theme: "pneumatic", text: "Quelle est la plage du manostat de régulation du compresseur ?", options: ["6,5–8,2 b", "8,2–9,7 b", "8,2–9,7 b avec régulation à 9,7 b", "7,6–9,5 b"], correct: {2}, explanation: "Le manostat de régulation est indiqué à 8,2–9,7 b, avec régulation à 9,7 b.", source: "p. 39", multi: false),
  Question(theme: "pneumatic", text: "Quelle est la plage du manostat de secours ?", options: ["7,6–9,5 b", "6,5–8,2 b", "8,2–9,7 b", "5–7 b"], correct: {0}, explanation: "Le manostat de secours est indiqué à 7,6–9,5 b.", source: "p. 39", multi: false),
  Question(theme: "pneumatic", text: "Combien de réservoirs principaux stockent l’air produit ?", options: ["2", "3", "4", "5"], correct: {2}, explanation: "L’air est stocké dans quatre réservoirs principaux.", source: "p. 39", multi: false),
  Question(theme: "pneumatic", text: "Quel est le volume total des réservoirs principaux ?", options: ["400 L", "600 L", "800 L", "1000 L"], correct: {2}, explanation: "Le volume total indiqué est de 800 litres.", source: "p. 39", multi: false),
  Question(theme: "pneumatic", text: "Sous quel seuil CP un compresseur est-il mis en service à la mise sous tension ?", options: ["9,7 b", "8,2 b", "7,6 b", "6,5 b"], correct: {1}, explanation: "En dessous de 8,2 b, un compresseur est mis en service.", source: "p. 39", multi: false),
  Question(theme: "pneumatic", text: "Sous quel seuil CP le deuxième compresseur est-il mis en route ?", options: ["8,2 b", "7,6 b", "6,5 b", "5,0 b"], correct: {1}, explanation: "En dessous de 7,6 b, le deuxième compresseur démarre.", source: "p. 39", multi: false),
  Question(theme: "pneumatic", text: "À quelle pression les compresseurs régulent-ils ?", options: ["6,5 b", "7,6 b", "8,2 b", "9,7 b"], correct: {3}, explanation: "La régulation est à 9,7 bars.", source: "p. 39", multi: false),
  Question(theme: "pneumatic", text: "Sous quel seuil CP un freinage d’urgence est-il activé ?", options: ["9,7 b", "8,2 b", "7,6 b", "6,5 b"], correct: {3}, explanation: "Sous 6,5 bars, un FU est activé.", source: "p. 39", multi: false),
  Question(theme: "pneumatic", text: "Quel est le rôle principal de la conduite CP ?", options: ["Distribuer l’air comprimé aux équipements pneumatiques", "Transmettre la puissance électrique", "Transmettre le signal PWM", "Commander les moteurs"], correct: {0}, explanation: "La CP parcourt la rame et alimente les équipements pneumatiques.", source: "p. 40", multi: false),
  Question(theme: "pneumatic", text: "Quels équipements sont alimentés par la CP ?", options: ["Freinage", "Suspension secondaire", "Pantographes et disjoncteurs", "Patins magnétiques"], correct: {0,1,2,3}, explanation: "Le livret cite ces fonctions parmi les équipements alimentés par la CP.", source: "p. 40", multi: true),
  Question(theme: "pneumatic", text: "À quoi sert la CB en mode secours ?", options: ["À contrôler la consigne de frein d’un engin non-NAT", "À alimenter les moteurs", "À commander les pantographes", "À charger les batteries"], correct: {0}, explanation: "La CB sert au contrôle de la consigne de frein en mode secours.", source: "p. 40", multi: false),
  Question(theme: "pneumatic", text: "Comment la CB peut-elle commander un freinage d’urgence en mode secours ?", options: ["Elle peut être mise à l’atmosphère par les BP-URG", "Elle ferme S25", "Elle commande le MCM", "Elle alimente le 72 V"], correct: {0}, explanation: "La CB peut être mise à l’atmosphère par les BP-URG.", source: "p. 40", multi: false),
  Question(theme: "pneumatic", text: "Que signifie LT T/F dans le livret ?", options: ["Ligne Train Traction et Freinage", "Ligne Transformateur Traction", "Ligne Technique Frein", "Ligne Tension/Fusible"], correct: {0}, explanation: "LT T/F est la Ligne Train Traction et Freinage.", source: "p. 41", multi: false),
  Question(theme: "pneumatic", text: "Quel type d’ordre transporte la LT T/F ?", options: ["Binaire", "Analogique continu", "Pneumatique", "Optique"], correct: {0}, explanation: "La LT T/F indique traction ou freinage par présence ou non de courant.", source: "p. 41", multi: false),
  Question(theme: "pneumatic", text: "Que transporte la PWM T/F ?", options: ["La puissance demandée", "La pression CP", "La tension caténaire", "La vitesse ligne"], correct: {0}, explanation: "La PWM T/F indique la puissance demandée.", source: "p. 41", multi: false),
  Question(theme: "pneumatic", text: "Comment la PWM T/F donne-t-elle son ordre ?", options: ["Par modulation de l’impulsion", "Par pression pneumatique", "Par variation de fréquence radio", "Par relais mécanique"], correct: {0}, explanation: "PWM signifie Pulse Width Modulation : modulation de largeur d’impulsion.", source: "p. 41", multi: false),
  Question(theme: "pneumatic", text: "Quel équipement traite les instructions du conducteur ?", options: ["EMCO", "BCU", "EPC", "ACM"], correct: {0}, explanation: "L’EMCO traite les instructions et émet les consignes de traction et freinage.", source: "p. 41", multi: false),
  Question(theme: "pneumatic", text: "Quel équipement interprète les consignes de traction de l’EMCO ?", options: ["PCU", "BCU", "EPC", "FIS"], correct: {0}, explanation: "Les consignes de traction sont interprétées par le PCU de la cabine en service.", source: "p. 41", multi: false),
  Question(theme: "pneumatic", text: "Combien de DCU y a-t-il par bogie moteur ?", options: ["1", "2", "3", "4"], correct: {0}, explanation: "Le livret indique un DCU par bogie moteur.", source: "p. 41", multi: false),
  Question(theme: "pneumatic", text: "Que commande le DCU ?", options: ["La puissance délivrée par le MCM aux deux moteurs", "Les portes", "Le FIS", "La tension caténaire"], correct: {0}, explanation: "Le DCU commande la puissance délivrée par l’onduleur MCM aux deux moteurs.", source: "p. 41", multi: false),
  Question(theme: "pneumatic", text: "La commande de traction est-elle asservie au freinage ?", options: ["Oui", "Non", "Uniquement en 25 kV", "Uniquement en UM"], correct: {0}, explanation: "Le livret précise que la commande de traction est asservie au freinage.", source: "p. 41", multi: false),
  Question(theme: "pneumatic", text: "Quel est l’effet automatique de l’anti-patinage ?", options: ["Réduire l’effort de traction", "Augmenter la pression CP", "Déclencher le FIS", "Ouvrir les DJ"], correct: {0}, explanation: "L’anti-patinage provoque une réduction automatique de l’effort de traction.", source: "p. 42", multi: false),
  Question(theme: "pneumatic", text: "Que doit faire l’ADC si LS-(DPAT) s’allume ?", options: ["Réduire l’effort de traction jusqu’à extinction de la lampe", "Augmenter la traction", "Déclencher le FU", "Abaisser les pantographes"], correct: {0}, explanation: "L’ADC doit réduire l’effort de traction jusqu’à extinction de LS-(DPAT).", source: "p. 42", multi: false),
  Question(theme: "pneumatic", text: "Quelle puissance utilise le mode nominal ?", options: ["60 %", "80 %", "90 %", "100 %"], correct: {1}, explanation: "Le mode nominal utilise 80 % de la puissance des moteurs.", source: "p. 42", multi: false),
  Question(theme: "pneumatic", text: "Quelle puissance utilise le mode PMAX ?", options: ["70 %", "80 %", "90 %", "100 %"], correct: {3}, explanation: "PMAX utilise 100 % de la puissance des moteurs.", source: "p. 42", multi: false),
  Question(theme: "pneumatic", text: "Dans quel cas le mode PMAX doit-il être utilisé ?", options: ["Uniquement en cas de retard", "À chaque démarrage", "Uniquement en gare", "Uniquement sous 25 kV"], correct: {0}, explanation: "Le livret précise que PMAX ne doit être utilisé qu’en cas de retard.", source: "p. 42", multi: false),
  Question(theme: "pneumatic", text: "Quel pictogramme permet de demander PMAX ?", options: ["Demander PMAX", "FIEF", "ZONE-UFR", "FU"], correct: {0}, explanation: "Le conducteur appuie sur le pictogramme gris « Demander PMAX ».", source: "p. 42", multi: false),
  Question(theme: "pneumatic", text: "Quel affichage confirme l’activation de PMAX ?", options: ["1/1 ou 2/2", "0/0", "FU", "UL=0V"], correct: {0}, explanation: "Le pictogramme est remplacé par « 1/1 ou 2/2 ».", source: "p. 42", multi: false),
  Question(theme: "pneumatic", text: "Jusqu’à quel événement PMAX reste-t-il actif ?", options: ["Jusqu’à maintien de service, dé-préparation ou désaccouplement", "Seulement 30 secondes", "Jusqu’au premier freinage", "Jusqu’à 15 km/h"], correct: {0}, explanation: "PMAX reste actif jusqu’à l’un de ces événements.", source: "p. 42", multi: false),
  Question(theme: "pneumatic", text: "Quels boutons sélectionnent le sens de marche ?", options: ["BPL-J(AV), BPL-J(0), BPL-J(AR)", "BP-URG, BPL(FIEF), BP-Q-BA", "BPO, BSI, BP(DJ)", "MCM, LCM, ACM"], correct: {0}, explanation: "Les trois boutons lumineux correspondent à avant, neutre et arrière.", source: "p. 42", multi: false),
  Question(theme: "pneumatic", text: "Quelle est la consigne maximale du mode CD ?", options: ["1 km/h", "3 km/h", "5 km/h", "10 km/h"], correct: {1}, explanation: "Le mode couplement/découplement limite la consigne à 3 km/h.", source: "p. 42", multi: false),
  Question(theme: "pneumatic", text: "Que signifie le mode 0 ?", options: ["Pas de consigne", "Traction maximale", "Freinage maximal", "Marche arrière"], correct: {0}, explanation: "Le mode 0 correspond à l’absence de consigne.", source: "p. 42", multi: false),
  Question(theme: "pneumatic", text: "À quoi est proportionnelle la consigne du mode CM ?", options: ["À la position du MP T/F", "À la pression CP", "À la tension caténaire", "À la température"], correct: {0}, explanation: "Le mode CM donne une consigne proportionnelle à la position du MP T/F.", source: "p. 42", multi: false),
  Question(theme: "pneumatic", text: "Comment le mode VI calcule-t-il la consigne ?", options: ["En comparant vitesse réelle et vitesse demandée", "En comparant la pression CP et la CG", "En comparant 1500 V et 25 kV", "En comparant les températures moteur"], correct: {0}, explanation: "Le mode VI compare la vitesse réelle et la vitesse demandée.", source: "p. 42", multi: false),
  Question(theme: "pneumatic", text: "Que fait l’EMCO en tenant compte du mode de conduite sélectionné ?", options: ["Il émet les consignes de traction et de freinage", "Il commande uniquement les portes", "Il mesure la tension caténaire", "Il produit l’air"], correct: {0}, explanation: "L’EMCO émet les consignes de traction et de freinage en fonction du mode choisi.", source: "p. 41", multi: false),
  Question(theme: "pneumatic", text: "Quel équipement commande les deux moteurs d’un bogie moteur via le MCM ?", options: ["DCU", "EPC", "FIS", "S25"], correct: {0}, explanation: "Le DCU commande la puissance du MCM vers les deux moteurs.", source: "p. 41", multi: false),
  Question(theme: "pneumatic", text: "Quelle information la LT T/F indique-t-elle ?", options: ["Si le conducteur ordonne traction ou freinage", "La vitesse réelle", "La pression des pantographes", "La température du transformateur"], correct: {0}, explanation: "La LT T/F est un ordre binaire traction/freinage.", source: "p. 41", multi: false),
  Question(theme: "pneumatic", text: "Quels paramètres caractérisent l’ordre PWM T/F ?", options: ["La puissance demandée et une modulation de l’impulsion", "La pression CP et le niveau de caisse", "La tension ligne et le nombre de caisses", "La vitesse et la température"], correct: {0}, explanation: "La PWM T/F indique la puissance demandée par modulation de l’impulsion.", source: "p. 41", multi: false),
  Question(theme: "braking", text: "Quels sont les trois types de freinage de la Z50000 ?", options: ["Mécanique", "Électrique", "Magnétique", "Hydraulique"], correct: {0,1,2}, explanation: "Le livret distingue freinage mécanique, électrique et magnétique.", source: "p. 43", multi: true),
  Question(theme: "braking", text: "Sur quoi agit le frein de service mécanique ?", options: ["Des disques sur chaque essieu", "Des patins magnétiques sur tous les essieux", "Des moteurs en génératrice", "La conduite blanche uniquement"], correct: {0}, explanation: "Le frein mécanique de service est réalisé par des freins à disque sur chaque essieu.", source: "p. 43", multi: false),
  Question(theme: "braking", text: "Quel organe applique les plaquettes sur les disques ?", options: ["Étrier de frein", "Pantographe", "BC", "MCM"], correct: {0}, explanation: "Chaque roue est freinée par un étrier qui applique une plaquette sur chaque disque.", source: "p. 43", multi: false),
  Question(theme: "braking", text: "Que contient chaque bogie pour fournir localement l’air de freinage ?", options: ["Un réservoir auxiliaire", "Un transformateur", "Un coffre batterie", "Un réservoir principal de 800 L"], correct: {0}, explanation: "Chaque bogie possède un réservoir auxiliaire local.", source: "p. 43", multi: false),
  Question(theme: "braking", text: "Quel robinet permet d’isoler le frein d’un bogie ?", options: ["RB(IS) F-BOG", "RB(IS)AUX", "ZDJ", "BPL(FIEF)"], correct: {0}, explanation: "RB(IS) F-BOG est le robinet d’isolement du frein du bogie.", source: "p. 43", multi: false),
  Question(theme: "braking", text: "Que provoque la mise en position isolée du RB(IS) F-BOG ?", options: ["La vidange pneumatique du circuit de freinage du bogie", "La fermeture des portes", "La montée du pantographe", "La mise en PMAX"], correct: {0}, explanation: "La mise en position isolée provoque la vidange pneumatique du circuit de freinage du bogie.", source: "p. 43", multi: false),
  Question(theme: "braking", text: "Sous quelles voitures/bogies sont situés les FEM ?", options: ["Bogies 1, 6, 7 et 9", "Bogies 2, 4 et 8", "Bogies 1, 2, 6 et 8", "Bogies 3, 5 et 7"], correct: {0}, explanation: "Les patins/FEM sont installés sur les bogies 1, 6, 7 et 9.", source: "p. 48", multi: false),
  Question(theme: "braking", text: "Combien de bogies sont équipés de FIS ?", options: ["2", "3", "4", "5"], correct: {1}, explanation: "Trois bogies sont équipés de FIS.", source: "p. 45", multi: false),
  Question(theme: "braking", text: "Quels bogies sont équipés du FIS ?", options: ["2, 6 et 8", "1, 6 et 9", "2, 4 et 8", "1, 7 et 9"], correct: {0}, explanation: "Le schéma du livret indique les bogies 2, 6 et 8.", source: "p. 45", multi: false),
  Question(theme: "braking", text: "De quoi est constitué le FIS ?", options: ["Un ressort et une électrovalve", "Deux moteurs", "Un disque et un patin", "Un réducteur et une bielle"], correct: {0}, explanation: "Le FIS est constitué d’un ressort et d’une électrovalve.", source: "p. 45", multi: false),
  Question(theme: "braking", text: "Quelle déclivité maximale le FIS peut-il immobiliser ?", options: ["3 mm/m", "5 mm/m", "8 mm/m", "10 mm/m"], correct: {1}, explanation: "Le livret indique une déclivité maximale de 5 mm/m.", source: "p. 45", multi: false),
  Question(theme: "braking", text: "Le serrage du frein de service par le MP T/F provoque quoi sur le FIS ?", options: ["Son desserrage", "Son serrage", "Son isolement", "Aucune action"], correct: {0}, explanation: "Le serrage du frein de service provoque le desserrage du FIS.", source: "p. 45", multi: false),
  Question(theme: "braking", text: "Dans quels cas le FIS se met-il automatiquement en œuvre ?", options: ["Chute de pression CP", "Maintien de service", "Dé-préparation", "PMAX"], correct: {0,1,2}, explanation: "Le FIS se met automatiquement en œuvre dans les trois premiers cas.", source: "p. 51", multi: true),
  Question(theme: "braking", text: "À quoi sert le FIEF ?", options: ["À l’EFAS pour immobiliser la rame et contrôler la descente des patins magnétiques", "À augmenter la puissance moteur", "À commander les portes", "À produire le 72 V"], correct: {0}, explanation: "Le FIEF sert à l’EFAS et permet notamment le contrôle des patins magnétiques.", source: "p. 47", multi: false),
  Question(theme: "braking", text: "Sur quelle platine se trouve le BPL(FIEF) ?", options: ["Platine 2", "Platine 3", "Platine 4", "Platine HT"], correct: {2}, explanation: "Le BPL(FIEF) est situé sur la platine n°4.", source: "p. 47", multi: false),
  Question(theme: "braking", text: "Que provoque la mise en action du FIEF ?", options: ["Le serrage des FIS", "Le desserrage des FIS", "La fermeture des DJ", "La descente normale des pantographes"], correct: {0}, explanation: "La mise en action du FIEF provoque le serrage des FIS.", source: "p. 47", multi: false),
  Question(theme: "braking", text: "Que simule le FIEF pour contrôler les patins magnétiques ?", options: ["Le seuil de vitesse de 15 km/h", "Le seuil de 0,5 km/h", "Le seuil de 5 km/h", "Le seuil de 30 km/h"], correct: {0}, explanation: "Le FIEF simule le seuil vitesse de 15 km/h.", source: "p. 47", multi: false),
  Question(theme: "braking", text: "Comment fonctionne le freinage électrique ?", options: ["Les moteurs fonctionnent en générateurs", "Les moteurs sont simplement coupés", "Les disques sont remplacés par les batteries", "Les pantographes sont toujours baissés"], correct: {0}, explanation: "Le frein électrique utilise le mode générateur des moteurs asynchrones.", source: "p. 48", multi: false),
  Question(theme: "braking", text: "Quelle est la priorité de l’énergie lors du freinage électrique ?", options: ["La récupération vers la caténaire", "Le rhéostat en premier", "Les batteries en premier", "La dissipation mécanique"], correct: {0}, explanation: "L’énergie est renvoyée en priorité vers la caténaire.", source: "p. 48", multi: false),
  Question(theme: "braking", text: "Que devient le complément d’énergie non admis par la caténaire ?", options: ["Il est dissipé en chaleur dans les rhéostats", "Il recharge les batteries", "Il alimente les portes", "Il est envoyé dans la CP"], correct: {0}, explanation: "Le complément est dissipé sous forme de chaleur dans les rhéostats.", source: "p. 48", multi: false),
  Question(theme: "braking", text: "Le freinage électrique reste-t-il actif lorsque le DJ est ouvert ?", options: ["Oui, en rhéostatique uniquement", "Non", "Oui, en récupération uniquement", "Uniquement sous 25 kV"], correct: {0}, explanation: "Il reste actif avec DJ ouvert, mais en rhéostatique uniquement.", source: "p. 48", multi: false),
  Question(theme: "braking", text: "À quelle vitesse les patins FEM s’abaissent-ils lors d’un FU selon le livret ?", options: ["Au-dessus de 5 km/h", "Au-dessus de 15 km/h", "Au-dessus de 30 km/h", "À toute vitesse"], correct: {1}, explanation: "Lors d’un FU à plus de 15 km/h, les patins s’abaissent puis sont magnétisés.", source: "p. 48", multi: false),
  Question(theme: "braking", text: "Quel délai est respecté entre le freinage par disques et par patins magnétiques ?", options: ["0,1 s", "0,5 s", "1 s", "2 s"], correct: {2}, explanation: "Une temporisation de 1 seconde est prévue.", source: "p. 48", multi: false),
  Question(theme: "braking", text: "Que font les patins magnétiques sous 15 km/h ?", options: ["Ils remontent et le frein électromagnétique est inactif", "Ils restent magnétisés", "Ils descendent automatiquement", "Ils commandent le FIS"], correct: {0}, explanation: "Le frein électromagnétique est inactif sous 15 km/h et les patins remontent.", source: "p. 48", multi: false),
  Question(theme: "braking", text: "Quelle est la première priorité de l’EMCO lors d’un freinage combiné ?", options: ["Freinage électrique des bogies moteurs", "Freinage mécanique des bogies moteurs", "Freinage mécanique des bogies porteurs", "FEM"], correct: {0}, explanation: "La première priorité est le freinage électrique des bogies moteurs.", source: "p. 49", multi: false),
  Question(theme: "braking", text: "Quelle est la deuxième priorité de l’EMCO lors d’un freinage combiné ?", options: ["Freinage électrique", "Complément mécanique des bogies moteurs", "Complément mécanique des bogies porteurs", "FIS"], correct: {1}, explanation: "La deuxième priorité est le complément mécanique des bogies moteurs.", source: "p. 49", multi: false),
  Question(theme: "braking", text: "Quelle est la troisième priorité de l’EMCO lors d’un freinage combiné ?", options: ["FEM", "Freinage électrique", "Complément mécanique des bogies porteurs", "FIEF"], correct: {2}, explanation: "La troisième priorité est le complément mécanique des bogies porteurs.", source: "p. 49", multi: false),
  Question(theme: "braking", text: "Jusqu’à quel effort correspond le freinage de service au point dur du MP T/F ?", options: ["2/4", "3/4", "4/4", "5/4"], correct: {2}, explanation: "Au point dur, l’effort commandé est maximum, 4/4.", source: "p. 50", multi: false),
  Question(theme: "braking", text: "À quel pourcentage de l’effort disponible correspond le freinage de service au point dur ?", options: ["75 %", "80 %", "90 %", "100 %"], correct: {2}, explanation: "Le livret indique 90 % de l’effort de freinage disponible.", source: "p. 50", multi: false),
  Question(theme: "braking", text: "Que commande le MP T/F après le point dur ?", options: ["Un freinage d’urgence", "Un freinage de service minimal", "Une traction maximale", "Le FIS"], correct: {0}, explanation: "Après le point dur, un FU est commandé.", source: "p. 50", multi: false),
  Question(theme: "braking", text: "Le freinage électrique est-il sollicité dans ce FU ?", options: ["Oui", "Non", "Uniquement en UM", "Uniquement sous 25 kV"], correct: {1}, explanation: "Le livret précise que le freinage électrique n’est pas sollicité.", source: "p. 50", multi: false),
  Question(theme: "braking", text: "Que fournit l’anti-enrayeur à l’EMCO et à la traction ?", options: ["Des seuils de vitesse", "La tension caténaire", "La pression des batteries", "Le niveau de caisse"], correct: {0}, explanation: "Le coffret anti-enrayeur fournit des seuils de vitesse à l’EMCO et à la traction.", source: "p. 52", multi: false),
  Question(theme: "braking", text: "Quel est le rôle de l’ATF ?", options: ["Couper la traction dès qu’un freinage est commandé", "Commander le FIS", "Commander les portes", "Ouvrir les DJ"], correct: {0}, explanation: "L’ATF coupe la traction dès qu’un freinage est commandé.", source: "p. 52", multi: false),
  Question(theme: "braking", text: "Pour quelle vitesse l’ATF est-il inhibé ?", options: ["V ≤ 2 km/h", "V ≤ 5 km/h", "V ≤ 10 km/h", "V ≤ 15 km/h"], correct: {1}, explanation: "L’ATF est inhibé pour V ≤ 5 km/h afin d’autoriser les démarrages en rampe.", source: "p. 52", multi: false),
  Question(theme: "braking", text: "Que fait l’AU en cas de freinage d’urgence ?", options: ["Il coupe l’effort de traction", "Il augmente l’effort de traction", "Il ouvre les portes", "Il commande PMAX"], correct: {0}, explanation: "L’AU coupe l’effort de traction en cas de freinage d’urgence.", source: "p. 52", multi: false),
  Question(theme: "braking", text: "Quelles conditions doivent être réunies pour permettre la traction vis-à-vis des portes et MM/CL ?", options: ["Portes fermées et verrouillées", "MM et CL rentrés et verrouillés", "FIS serrés", "Toutes les réponses"], correct: {0,1}, explanation: "La traction est autorisée si les portes sont fermées/verrouillées et les MM/CL rentrés/verrouillés.", source: "p. 52", multi: false),
  Question(theme: "braking", text: "Par quoi la LT FU est-elle alimentée ?", options: ["Batterie 72 V", "Réseau 230 V", "Caténaire 25 kV", "CP"], correct: {0}, explanation: "La LT FU est alimentée par la batterie 72 V.", source: "p. 53", multi: false),
  Question(theme: "braking", text: "Que provoque la non-alimentation de la LT FU ?", options: ["Le serrage maximum des paniers de frein et la mise en action du FEM sur les bogies équipés", "La montée des pantographes", "La fermeture de S25", "Le desserrage du FIS"], correct: {0}, explanation: "La LT FU non alimentée commande le serrage maximum et, via l’EPC, le FEM sur les bogies équipés.", source: "p. 53", multi: false),
  Question(theme: "braking", text: "Quels événements peuvent provoquer l’ouverture de C1URG et C2URG ?", options: ["Déclenchement VA/KVB/RS", "Position FU du MPT/F", "Signal d’alarme dans certains cas", "Toutes les réponses"], correct: {3}, explanation: "Le livret cite ces événements comme provoquant l’ouverture des contacts et la coupure de la ligne FU.", source: "p. 53", multi: false),
  Question(theme: "braking", text: "En mode secouru, comment une commande de frein d’un train non-Z50000 est-elle interprétée ?", options: ["CG pneumatique → CB → convertisseurs → PWM F", "CG → MCM → FIS", "CP → ACM → DJ", "CB → batteries → portes"], correct: {0}, explanation: "La CG arrive dans la CB, deux convertisseurs la transforment en courant électrique, puis le signal alimente la PWM F.", source: "p. 57", multi: false),
  Question(theme: "functions", text: "Combien de consoles IHM possède le poste de conduite ?", options: ["1", "2", "3", "4"], correct: {1}, explanation: "Le poste possède deux consoles IHM.", source: "p. 59", multi: false),
  Question(theme: "functions", text: "Quelles informations l’IHM CC affiche-t-elle ?", options: ["État des pantographes et disjoncteurs", "Sens de marche demandé", "Indicateur de vitesse de secours", "Effort-mètre traction/freinage"], correct: {0,1,2,3}, explanation: "Ces informations font partie de celles affichées sur l’IHM CC.", source: "p. 59", multi: true),
  Question(theme: "functions", text: "Où se trouve l’IHM SIAC ?", options: ["À droite du pupitre", "Face au conducteur uniquement", "Sur la platine HT", "Dans le compartiment batterie"], correct: {0}, explanation: "L’IHM SIAC est à droite du pupitre, hors vision centrale de l’ADC.", source: "p. 59", multi: false),
  Question(theme: "functions", text: "Que signale le pictogramme UL=0V ?", options: ["La présence ou non de la tension ligne", "La pression CP", "Le niveau de batterie", "La position du FIS"], correct: {0}, explanation: "UL=0V indique la présence ou non de la tension ligne.", source: "p. 59", multi: false),
  Question(theme: "functions", text: "Quel délai maximal d’initialisation du système KVB est indiqué ?", options: ["30 s", "60 s", "85 s", "120 s"], correct: {2}, explanation: "Le temps d’initialisation peut prendre jusqu’à 85 secondes.", source: "p. 59", multi: false),
  Question(theme: "functions", text: "Que provoque le déclenchement d’un automatisme de sécurité ?", options: ["La non-alimentation de C1URG/C2URG et le FU via la ligne FU", "L’ouverture automatique des portes", "La montée des pantographes", "La mise en PMAX"], correct: {0}, explanation: "Le déclenchement provoque la non-alimentation des relais de sécurité et le freinage d’urgence.", source: "p. 61", multi: false),
  Question(theme: "functions", text: "Les disjoncteurs sont-ils ouverts lors d’un FU provoqué par un automatisme ?", options: ["Oui", "Non", "Seulement en UM", "Seulement sous 25 kV"], correct: {1}, explanation: "Le livret précise que les disjoncteurs ne sont pas ouverts lors d’un FU automatisme.", source: "p. 61", multi: false),
  Question(theme: "functions", text: "Comment la traction est-elle coupée lors d’un FU automatisme ?", options: ["Par le système", "Par l’ouverture des DJ", "Par le FIS", "Par le SAI"], correct: {0}, explanation: "La traction est coupée par le système, sans ouverture des DJ.", source: "p. 61", multi: false),
  Question(theme: "functions", text: "Que faut-il effectuer pour réarmer un automatisme ?", options: ["Une commande de réarmement avec BP(DJ-réarmement automatisme)", "Une action sur le SAI", "Une mise à la terre", "Un débranchement batterie"], correct: {0}, explanation: "Le réarmement s’effectue par le BP dédié au réarmement automatisme.", source: "p. 61", multi: false),
  Question(theme: "functions", text: "Quelle lampe reste allumée jusqu’au passage du MPT/F à 0 après un FU automatisme ?", options: ["LS(FU)", "LS(DJ)", "LS(DF)SUSP", "LS(SI)AL"], correct: {0}, explanation: "LS(FU) reste allumée jusqu’au passage du MPT/F à 0.", source: "p. 61", multi: false),
  Question(theme: "functions", text: "Que surveille le système de détection incendie ?", options: ["Climatisations", "Convertisseurs", "Transformateurs", "Toutes les réponses"], correct: {3}, explanation: "La détection concerne les climatisations, convertisseurs et transformateurs.", source: "p. 61", multi: false),
  Question(theme: "functions", text: "Que fait le SIE après détection d’un défaut incendie ?", options: ["Il fait remonter l’information et isole le système", "Il augmente la puissance", "Il baisse les pantographes uniquement", "Il ouvre toutes les portes"], correct: {0}, explanation: "Le SIE fait remonter l’information et isole le système en cause.", source: "p. 61", multi: false),
  Question(theme: "functions", text: "Quelle largeur ont les portes coulissantes ?", options: ["1,50 m", "1,80 m", "1,95 m", "2,20 m"], correct: {2}, explanation: "Les portes sont indiquées à 1,95 m de large.", source: "p. 62", multi: false),
  Question(theme: "functions", text: "Sur un quai bas, que fait le système ?", options: ["Déploie les MM puis autorise l’ouverture côté quai", "Ne déploie aucune MM", "Déploie les CL uniquement", "Ouvre les deux côtés"], correct: {0}, explanation: "Pour un quai bas, les MM sont déployées puis l’ouverture côté quai est autorisée.", source: "p. 63", multi: false),
  Question(theme: "functions", text: "Sur un quai haut de 670 à 920 mm, les MM sont-elles déployées ?", options: ["Oui", "Non", "Seulement à 920 mm", "Seulement en UFR"], correct: {1}, explanation: "Le quai haut n’entraîne pas le déploiement des MM.", source: "p. 63", multi: false),
  Question(theme: "functions", text: "Sur un quai haut 920 mm UFR aux extrémités, que se passe-t-il ?", options: ["CL déployé puis ouverture automatique des portes côté quai aux extrémités", "MM déployées sur toute la rame", "Aucune ouverture automatique", "Ouverture des deux côtés"], correct: {0}, explanation: "Le livret prévoit le déploiement des CL puis l’ouverture automatique aux extrémités.", source: "p. 63", multi: false),
  Question(theme: "functions", text: "Quelles conditions permettent automatiquement l’autorisation d’ouverture et le déploiement MM/CL ?", options: ["Sélection du côté par balise Silec ou KVB", "Transmission de la hauteur par balise KVB", "Vitesse inférieure à 0,5 km/h", "Toutes les réponses"], correct: {3}, explanation: "Les trois conditions sont nécessaires dans la logique décrite.", source: "p. 64", multi: false),
  Question(theme: "functions", text: "Quel seuil de vitesse est utilisé pour considérer le train à l’arrêt pour les portes ?", options: ["0,5 km/h", "1,5 km/h", "2 km/h", "5 km/h"], correct: {0}, explanation: "Le seuil indiqué est inférieur à 0,5 km/h.", source: "p. 64", multi: false),
  Question(theme: "functions", text: "Quelle longueur de zone est créée par le système pour la présence du quai ?", options: ["256 m", "512 m", "768 m", "1024 m"], correct: {1}, explanation: "Une zone de 512 m est créée à partir des balises.", source: "p. 64", multi: false),
  Question(theme: "functions", text: "Combien de temps minimum les ronfleurs sont-ils émis avant la fermeture des portes ?", options: ["1 s", "2 s", "3 s", "5 s"], correct: {2}, explanation: "Les ronfleurs sont toujours émis au moins 3 secondes avant la fermeture.", source: "p. 65", multi: false),
  Question(theme: "functions", text: "Quelle position de Z(CO) FP émet les ronfleurs ?", options: ["R", "F", "0", "D"], correct: {0}, explanation: "La position R émet le signal sonore.", source: "p. 65", multi: false),
  Question(theme: "functions", text: "Quelle position de Z(CO) FP commande la fermeture ?", options: ["R", "F", "0", "D"], correct: {1}, explanation: "La position F commande la fermeture des portes.", source: "p. 65", multi: false),
  Question(theme: "functions", text: "Que se passe-t-il si la commande de fermeture est relâchée prématurément ?", options: ["La fermeture est annulée et les autorisations précédentes rétablies", "Les portes se verrouillent immédiatement", "Le FU est déclenché", "Le SAI est activé"], correct: {0}, explanation: "Le livret décrit cette annulation automatique.", source: "p. 65", multi: false),
  Question(theme: "functions", text: "Que se passe-t-il si une porte rencontre un obstacle pendant la fermeture ?", options: ["Elle s’arrête puis reprend à faible vitesse", "Elle se verrouille à pleine vitesse", "Elle ouvre l’autre côté", "Elle déclenche toujours un FU"], correct: {0}, explanation: "La porte s’arrête pour dégager l’obstacle puis reprend à faible vitesse.", source: "p. 65", multi: false),
  Question(theme: "functions", text: "Quel bouton efface les informations mémorisées de hauteur et de côté pour l’ouverture manuelle ?", options: ["BP(A-AUT-OP)", "BP(A-FP)GA", "BP(A-FP)DO", "BPL(FIEF)"], correct: {0}, explanation: "BP(A-AUT-OP) annule l’autorisation d’ouverture et efface hauteur et côté mémorisés.", source: "p. 66", multi: false),
  Question(theme: "functions", text: "Quelle zone fictive est créée lors d’une autorisation manuelle d’ouverture ?", options: ["128 m", "256 m", "512 m", "1024 m"], correct: {2}, explanation: "Une zone de balises fictive de 512 m est créée.", source: "p. 66", multi: false),
  Question(theme: "functions", text: "Lorsqu’on regarde une porte depuis l’extérieur, où se trouve le carré de condamnation des MM ?", options: ["Montant gauche", "Montant droit", "Au sol", "Au-dessus du voyant"], correct: {0}, explanation: "Le carré de condamnation des MM est dans le montant gauche.", source: "p. 67", multi: false),
  Question(theme: "functions", text: "Que trouve-t-on au niveau de chaque porte, sur le montant gauche côté intérieur, pour le SAI ?", options: ["Une poignée SAI et son carré de réarmement", "Un micro et haut-parleur", "Un BPL de déverrouillage de secours", "Toutes les réponses"], correct: {3}, explanation: "Le livret décrit ces équipements au niveau de chaque porte.", source: "p. 68", multi: false),
  Question(theme: "functions", text: "Que devient le voyant rouge du SAI lorsque l’interphonie est établie ?", options: ["Il reste clignotant", "Il devient fixe", "Il s’éteint immédiatement", "Il devient jaune"], correct: {1}, explanation: "Le voyant rouge clignote lors de l’action puis devient fixe lorsque l’interphonie est établie.", source: "p. 68", multi: false),
  Question(theme: "functions", text: "Quelle information visuelle extérieure indique la localisation d’un SAI tiré ?", options: ["Un voyant jaune clignotant", "Un voyant vert fixe", "Un voyant bleu", "Aucune"], correct: {0}, explanation: "Un voyant jaune clignotant est présent à l’extérieur de la voiture concernée.", source: "p. 68", multi: false),
  Question(theme: "functions", text: "Quels indices le conducteur constate-t-il en cabine lors de l’action sur un SAI ?", options: ["Des tops sonores", "Le clignotement du BP alarme de la RST", "Le pictogramme ALARME LS-SI(AL) fixe", "Toutes les réponses"], correct: {3}, explanation: "Le livret cite ces trois indices en cabine.", source: "p. 68", multi: false),
  Question(theme: "functions", text: "Combien de secondes d’images avant et après l’action SAI l’ADC peut-il visualiser pour lever un doute ?", options: ["3 s", "6 s", "10 s", "15 s"], correct: {1}, explanation: "Les images des 6 secondes avant et après l’action sont visualisables pour la voiture concernée.", source: "p. 69", multi: false),
  Question(theme: "functions", text: "Combien de SAI au maximum peuvent être pris en compte dans une communication étendue ?", options: ["1", "2", "3", "5"], correct: {2}, explanation: "La communication est limitée à 3 SAI.", source: "p. 69", multi: false),
  Question(theme: "functions", text: "Quelle action clôture la procédure SAI et supprime notamment l’écran de localisation ?", options: ["La commande de fermeture des portes par Z(CO)FP", "Le passage à 25 kV", "Le réarmement du FIS", "L’ouverture d’un DJ"], correct: {0}, explanation: "La commande de fermeture des portes par Z(CO)FP supprime l’écran et les voyants jaunes concernés.", source: "p. 69", multi: false),
  Question(theme: "functions", text: "À quel seuil de vitesse l’autorisation automatique de déverrouillage de secours est-elle donnée à l’arrêt ?", options: ["0,5 km/h", "1,5 km/h", "2 km/h", "5 km/h"], correct: {0}, explanation: "Le seuil vitesse d’arrêt indiqué est 0,5 km/h.", source: "p. 71", multi: false),
  Question(theme: "functions", text: "Que se passe-t-il pour les boutons d’appel UFR après les premiers tours de roue ?", options: ["Ils restent toujours actifs", "Ils sont inhibés", "Ils déclenchent le FU", "Ils commandent les portes"], correct: {1}, explanation: "Tous les boutons appel UFR sont actifs dans les premiers tours de roue puis sont inhibés.", source: "p. 72", multi: false),
  Question(theme: "functions", text: "Combien de caméras équipe chaque voiture ?", options: ["1", "2", "3", "4"], correct: {1}, explanation: "Chaque voiture est équipée de 2 caméras en quinconce.", source: "p. 73", multi: false),
  Question(theme: "functions", text: "Quelle est la capacité d’enregistrement en mode normal ?", options: ["24 h", "48 h", "72 h", "96 h"], correct: {2}, explanation: "La capacité indiquée en mode normal est de 72 heures.", source: "p. 73", multi: false),
  Question(theme: "functions", text: "Combien de temps supplémentaire est prévu en mode alarme ?", options: ["2 h", "4 h", "6 h", "10 h"], correct: {1}, explanation: "Le mode alarme apporte 4 heures supplémentaires.", source: "p. 73", multi: false),
  Question(theme: "functions", text: "Quelle durée maximale de conservation des enregistrements est indiquée ?", options: ["7 jours", "15 jours", "30 jours", "60 jours"], correct: {2}, explanation: "Le livret indique une conservation maximale de 30 jours, date des faits.", source: "p. 73", multi: false),
];
